import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void triplet_margin_loss_kernel(
    const T* __restrict__ Aptr,
    const T* __restrict__ Pptr,
    const T* __restrict__ Nptr,
    float* __restrict__ loss_sum,
    int D,
    float margin)
{
  const int row = blockIdx.x;
  const int tid = threadIdx.x;
  const int nthreads = blockDim.x;

  const T* a_row = Aptr + (size_t)row * D;
  const T* p_row = Pptr + (size_t)row * D;
  const T* n_row = Nptr + (size_t)row * D;

  // Represent each row as a CuTe tensor in global memory
  auto gA = make_tensor(make_gmem_ptr(a_row), make_shape(D), make_stride(Int<1>{}));
  auto gP = make_tensor(make_gmem_ptr(p_row), make_shape(D), make_stride(Int<1>{}));
  auto gN = make_tensor(make_gmem_ptr(n_row), make_shape(D), make_stride(Int<1>{}));

  float sum_pos = 0.0f;
  float sum_neg = 0.0f;

  // Strided partitioning across threads (cooperative tiled loop)
  for (int i = tid; i < D; i += nthreads) {
    float av = static_cast<float>(gA(i));
    float pv = static_cast<float>(gP(i));
    float nv = static_cast<float>(gN(i));
    float dp = av - pv;
    float dn = av - nv;
    sum_pos += dp * dp;
    sum_neg += dn * dn;
  }

  // Block-level reduction using shared memory
  extern __shared__ float smem[];
  float* shared_pos = smem;
  float* shared_neg = smem + nthreads;

  shared_pos[tid] = sum_pos;
  shared_neg[tid] = sum_neg;
  __syncthreads();

  for (int s = nthreads >> 1; s > 0; s >>= 1) {
    if (tid < s) {
      shared_pos[tid] += shared_pos[tid + s];
      shared_neg[tid] += shared_neg[tid + s];
    }
    __syncthreads();
  }

  if (tid == 0) {
    float dist_pos = sqrtf(shared_pos[0]);
    float dist_neg = sqrtf(shared_neg[0]);
    float loss = dist_pos - dist_neg + margin;
    loss = loss > 0.0f ? loss : 0.0f;
    atomicAdd(loss_sum, loss);
  }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin) {
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "All inputs must be CUDA tensors");
  TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
              "Inputs must be 2D tensors [N, D]");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive, negative must have the same shape");

  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();

  int64_t N = a_c.size(0);
  int64_t D = a_c.size(1);

  auto loss_sum = torch::zeros({1}, a_c.options().dtype(at::kFloat));

  const int threads = 256;
  dim3 block(threads);
  dim3 grid((unsigned)N);
  size_t smem_bytes = 2 * threads * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  AT_DISPATCH_FLOATING_TYPES(a_c.scalar_type(), "triplet_margin_loss_kernel", ([&] {
    triplet_margin_loss_kernel<scalar_t><<<grid, block, smem_bytes, stream>>>(
        a_c.data_ptr<scalar_t>(),
        p_c.data_ptr<scalar_t>(),
        n_c.data_ptr<scalar_t>(),
        loss_sum.data_ptr<float>(),
        (int)D,
        (float)margin
    );
  }));

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_kernel launch failed: ", cudaGetErrorString(err));

  auto mean_loss = loss_sum / static_cast<double>(N);
  return mean_loss.squeeze();
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Computes Triplet Margin Loss using a custom CUTE/CUDA kernel.

    Parameters:
        margin (float): The margin between the positive and negative samples.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin
        )

